<section class="page-heading"><div><div class="eyebrow">UN NOUVEAU POINT DE DÉPART</div><h1>Importez le travail.<br>Gardez l’élan.</h1><p>Un CSV, un aperçu, puis vos tickets au bon endroit.</p></div><a class="button subtle" href="/list">Revenir à la liste</a></section><section class="panel import-panel"><h2>1. Votre fichier</h2><form method="post" action="/import/preview" enctype="multipart/form-data" class="stack"><?= csrf() ?><input type="hidden" name="project_id" value="<?= (int)$project['id'] ?>"><input type="hidden" name="_return" value="/import"><label class="upload-area"><?= icon('upload') ?><strong>Choisir un fichier CSV</strong><span>UTF-8 · virgule ou point-virgule · 2 Mo / 500 lignes maximum</span><input type="file" name="csv" accept=".csv,text/csv" required></label><button class="button primary">Examiner le fichier</button></form></section>
<?php if($preview): ?><section class="panel import-panel"><h2>2. Faites correspondre les champs</h2><p><?= count($preview['rows']) ?> lignes seront créées dans <?= e(App\Models\Project::find((int)$preview['project_id'])['name']) ?>. L’import sera annulé entièrement si une ligne est invalide.</p><form method="post" action="/import" class="stack"><?= csrf() ?><input type="hidden" name="nonce" value="<?= e($preview['nonce']) ?>"><input type="hidden" name="_return" value="/import"><div class="mapping-grid"><?php foreach(['title'=>'Résumé *','description'=>'Description','type'=>'Type','status'=>'État','priority'=>'Priorité','start_date'=>'Date de début','due_date'=>'Échéance','estimated_hours'=>'Temps estimé (h)','labels'=>'Étiquettes'] as $key=>$label): ?><label><?= e($label) ?><select name="map[<?= e($key) ?>]" <?= $key==='title'?'required':'' ?>><option value="">Ignorer cette colonne</option><?php foreach($preview['headers'] as $header): ?><option value="<?= e($header) ?>" <?= $header===$key||($key==='title'&&in_array($header,['résumé','summary'],true))?'selected':'' ?>><?= e($header) ?></option><?php endforeach; ?></select></label><?php endforeach; ?></div><h3>Aperçu des 5 premières lignes</h3><div class="table-panel"><table class="ticket-table"><thead><tr><?php foreach($preview['headers'] as $h): ?><th><?= e($h) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach(array_slice($preview['rows'],0,5) as $row): ?><tr><?php foreach($row as $v): ?><td><?= e(mb_substr($v,0,100)) ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div><button class="button primary" data-confirm="Créer les tickets à partir de cet aperçu ?">Créer les <?= count($preview['rows']) ?> tickets</button></form></section><?php endif; ?>
